CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE,username TEXT UNIQUE,pass_hash TEXT,salt TEXT,bio TEXT DEFAULT '',created_at INTEGER);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER,exp INTEGER);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,text TEXT,image_key TEXT,created_at INTEGER);
CREATE TABLE IF NOT EXISTS likes(user_id INTEGER,post_id INTEGER,PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER,user_id INTEGER,text TEXT,created_at INTEGER);
CREATE TABLE IF NOT EXISTS follows(follower_id INTEGER,followee_id INTEGER,PRIMARY KEY(follower_id,followee_id));
CREATE TABLE IF NOT EXISTS blocks(user_id INTEGER,blocked_id INTEGER,PRIMARY KEY(user_id,blocked_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER,reporter_id INTEGER,reason TEXT,created_at INTEGER);
